int main() {
    // Define the coefficients of the polynomials
    vector<int> p1 = {7, -3, g};
    vector<int> p2 = {3, h, -8};

    // Calculate the product of the polynomials
    vector<int> product;
    for (int i = 0; i < p1.size(); i++) {
        for (int j = 0; j < p2.size(); j++) {
            product.push_back(p1[i] * p2[j]);
        }
    }

    // Sort the product vector in descending order
    sort(product.rbegin(), product.rend());

    // Print the product of the polynomials
    cout << "The product of the polynomials is: ";
    for (int i = 0; i < product.size(); i++) {
        cout << product[i];
        if (i < product.size() - 1) {
            cout << " + ";
        }
    }
    cout << endl;

    // Calculate the sum of g and h
    int g = product[0];
    int h = product[1];
    int sum = g + h;

    // Print the sum of g and h
    cout << "The sum of g and h is: " << sum << endl;

    return 0;
}

