draw(Circle((0,0),1));
draw((R + 0.1*(R - P))--P--(T + 0.1*(T - P)));
draw(A--B--O--cycle);

label("$A$", A, dir(270));
label("$B$", B, NW);
label("$O$", O, NE);
label("$P$", P, SW);
label("$R$", R, NW);
